// Para cada repositorio, obtener commits de las últimas 24 horas
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);

const formatDate = (date) => date.toISOString().split('T')[0];

const repos = items[0].json;
const results = [];

for (const repo of repos) {
  const repoId = repo.id;
  const repoName = repo.name;

  // Obtener commits del repositorio desde ayer
  const commitsUrl = `https://gitlab.com/api/v4/projects/${repoId}/repository/commits?since=${yesterday.toISOString()}&until=${now.toISOString()}`;

  results.push({
    repoId,
    repoName,
    repoUrl: repo.web_url,
    commitsUrl
  });
}

return results.map(item => ({
  json: item
}));

// Procesar commits por autor
const results = {};

for (const item of items) {
  const repoData = item.json;
  const commits = repoData.commits || [];

  for (const commit of commits) {
    const authorName = commit.author_name || 'Unknown';
    const authorEmail = commit.author_email || '';
    const commitDate = commit.committed_date.split('T')[0];

    if (!results[authorEmail]) {
      results[authorEmail] = {
        author_name: authorName,
        author_email: authorEmail,
        commit_dates: {},
        total_commits: 0,
        total_lines_added: 0,
        total_lines_deleted: 0,
        total_files_changed: 0
      };
    }

    const authorData = results[authorEmail];

    // Contar commits por fecha
    if (!authorData.commit_dates[commitDate]) {
      authorData.commit_dates[commitDate] = 0;
    }
    authorData.commit_dates[commitDate]++;
    authorData.total_commits++;

    // Obtener estadísticas del commit
    const stats = commit.stats || {};
    authorData.total_lines_added += stats.additions || 0;
    authorData.total_lines_deleted += stats.deletions || 0;
    authorData.total_files_changed += stats.total || 0;
  }
}

// Convertir a array
const output = Object.values(results).map(data => ({
  json: {
    ...data,
    commit_dates: JSON.stringify(data.commit_dates)
  }
}));

return output;

// Preparar datos para logs
const today = new Date().toISOString().split('T')[0];
const totalRecords = items.length;

return [{
  json: {
    workflow_name: 'GitLab Daily Metrics',
    execution_date: new Date().toISOString(),
    status: 'completed',
    records_processed: totalRecords,
    duration_ms: Date.now() - workflow_start_time
  }
}];
